static int uow_commit(uow *u, sqlite3 *db) {
    if (sqlite3_exec(db, "BEGIN IMMEDIATE", 0, 0, 0) != SQLITE_OK) return -1;
    for (size_t i = 0; i < u->n_new;     i++) insert_row(db, u->new_[i]);
    for (size_t i = 0; i < u->n_dirty;   i++) update_row(db, u->dirty[i]);
    for (size_t i = 0; i < u->n_removed; i++) delete_row(db, u->removed[i]);
    if (sqlite3_exec(db, "COMMIT", 0, 0, 0) != SQLITE_OK) {
        sqlite3_exec(db, "ROLLBACK", 0, 0, 0);
        return -1;
    }
    uow_reset(u);   /* lists must be cleared, or the next commit re-writes them */
    return 0;
}
